// Pure helpers for the committed demo dataset data/sample-data.json (sample customers and historical
// orders, generated by `node tools/build-sample-data.mjs`). No DB, no DOM: importable in Node.
//
// The file is generated relative to a fixed `anchor` instant. At install time the seed moves every
// timestamp forward (or back) by whole days so the newest sample order lands on the install day:
// the dashboard's "last 30 days" chart is populated whenever the demo is first opened, times of day
// are preserved, and no sample order is ever dated in the future.

export const DAY_MS = 86400000;

const pad = (n) => String(n).padStart(2, '0');
const ymdUtc = (d) => `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}`;

/** Whole days to add so the anchor maps onto `now`'s day (floor: never into the future). */
export const shiftDays = (anchorIso, now = new Date()) => Math.floor((now.getTime() - new Date(anchorIso).getTime()) / DAY_MS);

/** Copy of the dataset with every timestamp moved by whole days; order ids re-dated (suffix kept). */
export function shiftSampleData(data, now = new Date()) {
  const days = shiftDays(data.anchor, now);
  const ms = days * DAY_MS;
  const mv = (iso) => (iso ? new Date(new Date(iso).getTime() + ms).toISOString() : iso);
  const orders = (data.orders || []).map((o) => {
    const createdAt = mv(o.createdAt);
    return {
      ...o,
      id: `MARIAS-${ymdUtc(new Date(createdAt))}-${o.id.split('-').at(-1)}`,
      createdAt,
      payment: o.payment && o.payment.simulatedAt ? { ...o.payment, simulatedAt: mv(o.payment.simulatedAt) } : o.payment,
      history: (o.history || []).map((h) => ({ ...h, at: mv(h.at) })),
    };
  });
  const customers = (data.customers || []).map((c) => ({
    ...c, createdAt: mv(c.createdAt), updatedAt: mv(c.updatedAt), lastOrderAt: mv(c.lastOrderAt),
  }));
  return { ...data, anchor: mv(data.anchor), shiftedDays: days, orders, customers };
}

/** Coupons with the sample orders' usage added to usedCount (inputs untouched). */
export function withCouponUsage(coupons, usage = {}) {
  return (coupons || []).map((c) => ({ ...c, usedCount: (Number(c.usedCount) || 0) + (Number(usage[c.code]) || 0) }));
}
